-- APPLIED to production 2026-11-01 (README.md Status).
--
-- MICHELIN Poland 2026 (announced 27 May 2026) and Türkiye 2026 (announced 4 Dec 2025),
-- plus the 2026 MICHELIN Key hotels of both (global Key article, 18 Sep 2026: Poland 14,
-- Türkiye 23). Brings every PL/TR restaurant's stars and every PL/TR Key hotel's Key in
-- line with MICHELIN's live selection, adds what the catalogue lacks, and completes the
-- existing rows (fill-only). Generated by build_pl_tr.py; evidence per row in
-- pl_tr_restaurants_2026.csv, pl_tr_key_hotels_2026.csv and match_report.csv.
--
-- Restaurants: 23 added (rest_3901..rest_3923), 1 star import error corrected in place,
--   4 existing rows filled, 5 michelin_url moved to MICHELIN's current page.
-- Hotels: 25 Key hotels added (hotel_2901..hotel_2925), 4 Keys corrected in place.
-- Locations: 4 existing restaurants moved to MICHELIN's pin and address.
-- Links: 2; property_name: 2.
-- No Google Place ID is written (no Google access in this pass).
--
-- PREREQUISITE: supabase/migrations/20261031180000_add_pl_tr_2026_cities.sql.
-- One transaction; every check raises and rolls the whole file back.
-- Run: supabase db query --linked -f <absolute path to this file>

begin;

-- 0. production is still the export of 2026-11-01T19:19 UTC
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code in ('PL', 'TR');
  if n <> 5 then raise exception 'expected 5 PL/TR restaurants (export), found % -- production changed', n; end if;
  select count(*) into n from public.hotels where country_code in ('PL', 'TR');
  if n <> 13 then raise exception 'expected 13 PL/TR hotels (export), found % -- production changed', n; end if;
  select count(*) into n from (values ('rest_0010', 'Araka', 'TR'), ('rest_0015', 'Bottiglieria 1881', 'PL'), ('rest_0071', 'Neolokal', 'TR'), ('rest_0097', 'Sankai by Nagaya', 'TR'), ('rest_0112', 'Turk Fatih Tutak', 'TR'), ('hotel_306', 'Jaskółka Dom i SPA', 'PL'), ('hotel_307', 'Zamek Łeba', 'PL'), ('hotel_308', 'Raffles Europejski Warsaw', 'PL'), ('hotel_309', 'Hotel Copernicus', 'PL'), ('hotel_310', 'Stradom House, Autograph Collection', 'PL'), ('hotel_311', 'Hotel Altus Palace', 'PL'), ('hotel_312', 'Pałac Ciekocinko Hotel Resort & Wellness', 'PL'), ('hotel_313', 'Hotel Bristol, A Luxury Collection Hotel, Warsaw', 'PL'), ('hotel_314', 'EN Hotel', 'PL'), ('hotel_315', 'Quadrille', 'PL'), ('hotel_316', 'H15 Palace, a Luxury Collection Hotel', 'PL'), ('hotel_758', 'Maçakızı', 'TR'), ('hotel_783', 'The Peninsula Istanbul', 'TR')) e(code, name, cc)
   where not exists (select 1 from public.restaurants r where r.restaurant_code = e.code and r.name = e.name and r.country_code = e.cc)
     and not exists (select 1 from public.hotels h where h.hotel_code = e.code and h.name = e.name and h.country_code = e.cc);
  if n <> 0 then raise exception '% exported codes no longer carry their exported name', n; end if;
  if exists (select 1 from public.restaurants where restaurant_code = any(array['rest_3901', 'rest_3902', 'rest_3903', 'rest_3904', 'rest_3905', 'rest_3906', 'rest_3907', 'rest_3908', 'rest_3909', 'rest_3910', 'rest_3911', 'rest_3912', 'rest_3913', 'rest_3914', 'rest_3915', 'rest_3916', 'rest_3917', 'rest_3918', 'rest_3919', 'rest_3920', 'rest_3921', 'rest_3922', 'rest_3923']))
  then raise exception 'restaurant codes rest_3901..rest_3923 are no longer free'; end if;
  if exists (select 1 from public.hotels where hotel_code = any(array['hotel_2901', 'hotel_2902', 'hotel_2903', 'hotel_2904', 'hotel_2905', 'hotel_2906', 'hotel_2907', 'hotel_2908', 'hotel_2909', 'hotel_2910', 'hotel_2911', 'hotel_2912', 'hotel_2913', 'hotel_2914', 'hotel_2915', 'hotel_2916', 'hotel_2917', 'hotel_2918', 'hotel_2919', 'hotel_2920', 'hotel_2921', 'hotel_2922', 'hotel_2923', 'hotel_2924', 'hotel_2925']))
  then raise exception 'hotel codes hotel_2901..hotel_2925 are no longer free'; end if;
end $$;

-- 1. Key import errors: a 2026 launch row (announced_on NULL) whose value MICHELIN's 2026 page
--    contradicts; corrected in place to 2026 (QA-384 shape). No 2025 value is asserted.
create temp table _kfix (code text primary key, keys smallint, was smallint) on commit drop;
insert into _kfix values
    ('hotel_311', 1, 2),
    ('hotel_313', 1, 2),
    ('hotel_306', 2, 1),
    ('hotel_307', 1, 2);
do $$
declare n int;
begin
  select count(*) into n from _kfix k join public.hotels h on h.hotel_code = k.code and h.michelin_keys = k.was
    join public.award_history a on a.entity_type = 'hotel' and a.entity_id = h.id and a.award_type = 'michelin_keys'
   where a.is_current and a.guide_year = 2026 and a.award_value = k.was and a.announced_on is null;
  if n <> 4 then raise exception '% of 4 Key launch rows found as exported -- has this file run?', n; end if;
end $$;
update public.award_history a set award_value = k.keys
  from _kfix k, public.hotels h
 where h.hotel_code = k.code and a.entity_type = 'hotel' and a.entity_id = h.id and a.award_type = 'michelin_keys'
   and a.is_current and a.guide_year = 2026 and a.award_value = k.was;
update public.hotels h set michelin_keys = k.keys, updated_at = now()
  from _kfix k where h.hotel_code = k.code and h.michelin_keys = k.was;

