    ('rest_3921', 'TR', 'Revithia', 1, 'Ürgüp', 'Temenni Mahallesi, Eski Kayakapı Mahallesi, Davut Ağa Sokak No:1, 50400 Ürgüp', 34.9066582, 38.6361046, 'https://guide.michelin.com/en/nevsehir/urgup_2827493/restaurant/revithia', 'https://www.kayakapi.com/revithia', '+90 384 341 88 77', 'Kayakapi Premium Caves - Cappadocia', date '2025-12-04'),
    ('rest_3922', 'TR', 'Teruar Urla', 1, 'Izmir', 'Kusçular Mahallesi, 8028. Sokak No:16, Urla, 35437 Izmir', 26.739059, 38.2524197, 'https://guide.michelin.com/en/izmir/izmir_2809416/restaurant/teruar-urla', 'https://www.teruarurla.com/', NULL, NULL, date '2025-12-04'),
    ('rest_3923', 'TR', 'Vino Locale', 2, 'Izmir', 'Kuşçular Mahallesi, 8037. Sokak No:3, Urla, 35430 Izmir', 26.7467029, 38.2808906, 'https://guide.michelin.com/en/izmir/izmir_2809416/restaurant/vino-locale', 'https://www.urlavinolocale.com', '+90 533 321 84 66', NULL, date '2025-12-04');
do $$
declare bad text;
begin
  select string_agg(x.name || ' (' || x.city || ')', ', ') into bad from _newr x
   where (select count(*) from public.cities c where c.country_code = x.cc and c.name = x.city) <> 1;
  if bad is not null then raise exception 'city does not resolve to exactly one row (run the migration first?): %', bad; end if;
  select string_agg(x.name, ', ') into bad from _newr x join public.restaurants r on r.michelin_url = x.michelin_url;
  if bad is not null then raise exception 'already present (michelin_url): %', bad; end if;
end $$;
insert into public.restaurants (restaurant_code, name, michelin_stars, inclusion_reason, city_id, country_code,
                                address, location, michelin_url, website_url, phone, property_name)
select x.code, x.name, x.stars, 'michelin_star',
       (select c.id from public.cities c where c.country_code = x.cc and c.name = x.city), x.cc,
       x.address, ST_SetSRID(ST_MakePoint(x.lon, x.lat), 4326)::geography,
       x.michelin_url, x.website_url, x.phone, x.property_name
  from _newr x;
insert into public.award_history (entity_type, entity_id, guide_year, award_type, award_value, is_current, announced_on)
select 'restaurant', r.id, 2026, 'michelin_stars', x.stars, true, x.announced
  from _newr x join public.restaurants r on r.restaurant_code = x.code;

-- 5. existing restaurants: fill-only phone/website (each confirmed on the venue's own site), and
--    michelin_url moved from the old nl/nl page to MICHELIN's current page (same slug; guarded on the old value)
create temp table _fill (code text primary key, phone text, website_url text) on commit drop;
insert into _fill values
    ('rest_0010', '+90 533 392 72 23', 'https://araka.com.tr/'),
    ('rest_0071', NULL, 'https://www.neolokal.com/'),
    ('rest_0097', '+90 532 379 19 97', 'https://sankai.com.tr/'),
    ('rest_0112', '+90 530 051 83 04', 'https://www.turkft.com/');
update public.restaurants r set phone = f.phone, updated_at = now() from _fill f where r.restaurant_code = f.code and f.phone is not null and r.phone is null;
update public.restaurants r set website_url = f.website_url, updated_at = now() from _fill f where r.restaurant_code = f.code and f.website_url is not null and r.website_url is null;
create temp table _url (code text primary key, was text, url text) on commit drop;
insert into _url values
    ('rest_0015', 'https://guide.michelin.com/nl/nl/lesser-poland/krakow/restaurant/bottiglieria-1881', 'https://guide.michelin.com/en/lesser-poland/krakow/restaurant/bottiglieria-1881'),
    ('rest_0010', 'https://guide.michelin.com/nl/nl/istanbul/istanbul/restaurant/araka', 'https://guide.michelin.com/en/istanbul-province/istanbul/restaurant/araka'),
    ('rest_0071', 'https://guide.michelin.com/nl/nl/istanbul/istanbul/restaurant/neolokal', 'https://guide.michelin.com/en/istanbul-province/istanbul/restaurant/neolokal'),
    ('rest_0097', 'https://guide.michelin.com/nl/nl/istanbul/istanbul/restaurant/sankai-by-nagaya', 'https://guide.michelin.com/en/istanbul-province/istanbul/restaurant/sankai-by-nagaya'),
    ('rest_0112', 'https://guide.michelin.com/nl/nl/istanbul/istanbul/restaurant/turk-fatih-tutak', 'https://guide.michelin.com/en/istanbul-province/istanbul/restaurant/turk-fatih-tutak');
do $$
declare n int;
begin
  select count(*) into n from _url u join public.restaurants r on r.restaurant_code = u.code and r.michelin_url = u.was;
  if n <> 5 then raise exception '% of 5 stored michelin_url values found as exported', n; end if;
  if exists (select 1 from _url u join public.restaurants r on r.michelin_url = u.url) then
    raise exception 'a current MICHELIN url is already used by another row'; end if;
end $$;
update public.restaurants r set michelin_url = u.url, updated_at = now()
  from _url u where r.restaurant_code = u.code and r.michelin_url = u.was;

-- 5b. location and address: stored point more than 500 m from MICHELIN's pin (three Istanbul
--    restaurants that moved, per their old stored address; Bottiglieria's point mis-geocoded with the
--    right address). Guarded on the old point within 5 m and the old address.
create temp table _loc (code text primary key, old_lat float8, old_lon float8, old_address text,
                       lat float8, lon float8, address text) on commit drop;
insert into _loc values
    ('rest_0015', 50.0595, 19.9431, 'ul. Bocheńska 5, 31-061 Kraków', 50.0486603, 19.9460552, 'ul. Bocheńska 5, 31-061 Kraków'),
    ('rest_0010', 41.0324, 28.9791, 'Tomtom Kaptan Sokak 18, 34433 Istanbul', 41.1171693, 29.0630471, 'Kapalı Bakkal Sokak No:8, Yeniköy/Sarıyer, 34464 Istanbul'),
    ('rest_0097', 41.0774, 28.9944, 'Yıldız Posta Cad. 27, 34394 Istanbul', 41.0779114, 29.0441298, 'Bebek, Cevdet Paşa Caddesi No:34, Beşiktaş, 34342 Istanbul'),
    ('rest_0112', 41.0314, 28.9921, 'Meclis-i Mebusan Cd., 34427 Istanbul', 41.0584197, 28.9775024, 'Bomonti, Cumhuriyet Hacıahmet Silahşör Caddesi, Yeniyol Sokak No:2, Şişli, 34440 Istanbul');
do $$
declare n int;
begin
  select count(*) into n from _loc l join public.restaurants r on r.restaurant_code = l.code
   where r.address = l.old_address
     and ST_DWithin(r.location, ST_SetSRID(ST_MakePoint(l.old_lon, l.old_lat), 4326)::geography, 5);
  if n <> 4 then raise exception '% of 4 stored locations found as exported -- has this file run?', n; end if;
end $$;
update public.restaurants r set location = ST_SetSRID(ST_MakePoint(l.lon, l.lat), 4326)::geography,
       address = l.address, updated_at = now()
  from _loc l where r.restaurant_code = l.code and r.address = l.old_address;

-- 6. links to hotels in `hotels`, each from MICHELIN's own pages (evidence column)
create temp table _links (hotel_code text, restaurant_code text, confidence text, evidence text) on commit drop;
insert into _links values
    ('hotel_2912', 'rest_3913', 'exact', 'MICHELIN''s Casa Lavanda review: ''The family-run business includes both a hotel and this restaurant''; restaurant and Key-hotel pages give the same address (Seçilmiş Sokak No:2, Ulupelit, Şile) and phone; pins 34 m apart. 2026-11-01.'),
    ('hotel_758', 'rest_3915', 'exact', 'MICHELIN''s Maçakızı review: ''you arrive at this luxury hotel (the rooms are gorgeous!)''; restaurant and hotel pages give the same phone (+90 252 311 24 00) and website (macakizi.com); pins 95 m apart. 2026-11-01.');
do $$
declare n int;
begin
  select count(*) into n from _links l join public.hotels h on h.hotel_code = l.hotel_code
    join public.restaurants r on r.restaurant_code = l.restaurant_code
   where r.property_name is null;
  if n <> 2 then raise exception 'links: % of 2 hotel/restaurant pairs resolve', n; end if;
end $$;
insert into public.hotel_restaurants (hotel_id, restaurant_id, link_confidence, evidence, verified_at)
select h.id, r.id, l.confidence, l.evidence, now()
  from _links l join public.hotels h on h.hotel_code = l.hotel_code join public.restaurants r on r.restaurant_code = l.restaurant_code
on conflict (hotel_id, restaurant_id) do nothing;

-- 7. post-conditions: MICHELIN's live 2026 selection exactly
do $$
declare n int;
begin
  select count(*) into n from public.restaurants where country_code = 'PL' and michelin_stars = 3;
  if n <> 0 then raise exception 'PL: expected 0 3-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'PL' and michelin_stars = 2;
  if n <> 1 then raise exception 'PL: expected 1 2-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'PL' and michelin_stars = 1;
  if n <> 10 then raise exception 'PL: expected 10 1-star, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'PL' and michelin_keys = 3;
  if n <> 0 then raise exception 'PL: expected 0 3-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'PL' and michelin_keys = 2;
  if n <> 5 then raise exception 'PL: expected 5 2-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'PL' and michelin_keys = 1;
  if n <> 9 then raise exception 'PL: expected 9 1-Key hotels, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'TR' and michelin_stars = 3;
  if n <> 0 then raise exception 'TR: expected 0 3-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'TR' and michelin_stars = 2;
  if n <> 2 then raise exception 'TR: expected 2 2-star, found %', n; end if;
  select count(*) into n from public.restaurants where country_code = 'TR' and michelin_stars = 1;
  if n <> 15 then raise exception 'TR: expected 15 1-star, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'TR' and michelin_keys = 3;
  if n <> 1 then raise exception 'TR: expected 1 3-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'TR' and michelin_keys = 2;
  if n <> 3 then raise exception 'TR: expected 3 2-Key hotels, found %', n; end if;
  select count(*) into n from public.hotels where country_code = 'TR' and michelin_keys = 1;
  if n <> 19 then raise exception 'TR: expected 19 1-Key hotels, found %', n; end if;
  select count(*) into n from public.restaurants r where r.country_code in ('PL', 'TR')
     and (select count(*) from public.award_history ah where ah.entity_type = 'restaurant' and ah.entity_id = r.id
           and ah.award_type = 'michelin_stars' and ah.is_current and ah.award_value is not distinct from r.michelin_stars) <> 1;
  if n <> 0 then raise exception '% PL/TR restaurants without exactly one current star row equal to michelin_stars', n; end if;
  select count(*) into n from public.hotels h where h.country_code in ('PL', 'TR') and h.michelin_keys is not null
     and (select count(*) from public.award_history a where a.entity_type = 'hotel' and a.entity_id = h.id
           and a.award_type = 'michelin_keys' and a.is_current and a.award_value = h.michelin_keys) <> 1;
  if n <> 0 then raise exception '% PL/TR Key hotels without exactly one current Key row equal to michelin_keys', n; end if;
  select count(*) into n from public.restaurants r where r.country_code in ('PL', 'TR') and r.property_name is not null
     and exists (select 1 from public.hotel_restaurants hr where hr.restaurant_id = r.id);
  if n <> 0 then raise exception '% restaurants have both a hotel link and a property_name', n; end if;
end $$;

commit;
